properties.query:
//Detects the removal of the registry key that controls script warning in excel
let eventtype = dynamic(["RegistryValueSet"]);
let RegistryValue = dynamic(["PythonFunctionWarnings"]);
let RegistryValueData = dynamic(["DWORD (0x00000000)"]);
_Im_RegistryEvent(eventtype_in=eventtype,registryvalue_has_any=RegistryValue,registrydata_has_any=RegistryValueData)
| where RegistryKey contains "\\microsoft\\office" and RegistryKey contains "\\excel\\security"
| extend
    Computer = tostring(column_ifexists("DvcHostname", "")),
    Account = tostring(column_ifexists("ActorUsername", "")),
    CommandLine = tostring(column_ifexists("ActingProcessCommandLine", "")),
    ProcessId = tostring(column_ifexists("ActingProcessId", ""))
